import utilSrv from "./js/base/utils"
import messageSrv from "./js/base/m-sender"
(function() {
    var XHR  = window.XMLHttpRequest.prototype;
    var open = XHR.open;
    var send = XHR.send;
    window.oFetch = window.fetch;
    let origFetch = window.fetch;
    XHR.open = function (method, url) {
        this._method = method;
        this._url = url;
        return open.apply(this, arguments);
    };

    //监控视频地址
    const videoSrc = (urlStr) => {
        const src = urlStr? urlStr.toLowerCase():'';
        if (!src) {//地址空的情况
            return false;
        }
        if (src.includes('.m3u8') || src.includes('.flv') || src.includes('.mp4')) {
            messageSrv.pagePostMessage({ type: utilSrv.netReqFetch,
                status: 200, url:urlStr, data: urlStr });
            return true;
        }
        return false;
    }

    //将响应发送到 content script
    const XHRNotify = async(xhr) => {
        if (utilSrv.isResourceSkip(xhr._url)) {
            return;//静态资源跳过
        }
        let data = '';
        utilSrv.Write(utilSrv.INFO, "发送监听通知",
            xhr.status, xhr.responseType, xhr._url);
        try {
            //流媒体二进制的数据直接跳过了
            if (!xhr.responseType || xhr.responseType == 'json' ||
                 xhr.responseType == 'text' ||  xhr.responseType == 'document') {
                if (xhr.responseType == 'json') {
                    data = JSON.stringify(xhr.response);     
                } else {//流体数据不做处理
                    data = xhr.responseText || xhr.response;
                }
                messageSrv.pagePostMessage({ type: utilSrv.netReqXhr, 
                    status: xhr.status, url:xhr._url, data: data });
            }
        } catch (err) {
            utilSrv.Write(utilSrv.ERROR, "XHRNotify错误", err);
        }
    };

    try {
        XHR.send = function (postData) {
            utilSrv.Write(utilSrv.INFO, "xhr request",
                 this._method, this._url, postData)
            this.addEventListener('load', function () {
                if (utilSrv.NetSniffer.Check(this._url)) {
                    if (!videoSrc(this._url)) {
                        XHRNotify(this);
                    }//非监控视频地址
                }
            });
            return send.apply(this, arguments);
        };

        window.fetch = async function (...args) {
            const response = await origFetch(...args);
            const urlStr = args[0];
            utilSrv.Write(utilSrv.INFO, 'fetch request:', args)
            if (utilSrv.NetSniffer.Check(urlStr)) {
                if (videoSrc(urlStr)) {
                    return response;//监控视频地址
                } 
                if (utilSrv.isResourceSkip(urlStr)) {
                    return response;//静态资源跳过
                }
                utilSrv.Write(utilSrv.INFO, "监听拦截", urlStr)
                try {//提取数据的逻辑
                    //将响应发送到 content script
                    utilSrv.Write(utilSrv.INFO, "发送监听通知", response.status, urlStr);
                    const body = await response.clone().text();//将响应发送到 send to content script
                    messageSrv.pagePostMessage({ type: utilSrv.netReqFetch,
                        status: response.status, url:urlStr, data: body });
                } catch (err) {//异常逻辑
                    utilSrv.Write(utilSrv.ERROR, err);
                }
            }
            return response;
        }
    } catch (error) {
        utilSrv.Write(utilSrv.ERROR, "异常数据", error)
    }
})();
